module gem_smash_solver (input clk, input rst_n, input start, input [15:0][15:0] gem_values, output reg [31:0] max_earnings, output reg done);localparam IDLE = 3'd0, STAGE1 = 3'd1, STAGE2 = 3'd2, DONE = 3'd3;reg [2:0] state, next_state;reg [31:0] total_positive_reg;reg [15:0] max_flow_reg;reg [10:0] cycle_count;reg [15:0] residual [18][18];always_ff @(posedge clk) begin if (!rst_n) begin state <= IDLE; total_positive_reg <= 0; max_flow_reg <= 0; cycle_count <= 0; done <= 0; end else begin state <= next_state; if (state == STAGE1) begin integer total_pos; total_pos = 0; if (gem_values[0] > 0) total_pos += gem_values[0]; if (gem_values[1] > 0) total_pos += gem_values[1]; if (gem_values[2] > 0) total_pos += gem_values[2]; if (gem_values[3] > 0) total_pos += gem_values[3]; if (gem_values[4] > 0) total_pos += gem_values[4]; if (gem_values[5] > 0) total_pos += gem_values[5]; if (gem_values[6] > 0) total_pos += gem_values[6]; if (gem_values[7] > 0) total_pos += gem_values[7]; if (gem_values[8] > 0) total_pos += gem_values[8]; if (gem_values[9] > 0) total_pos += gem_values[9]; if (gem_values[10] > 0) total_pos += gem_values[10]; if (gem_values[11] > 0) total_pos += gem_values[11]; if (gem_values[12] > 0) total_pos += gem_values[12]; if (gem_values[13] > 0) total_pos += gem_values[13]; if (gem_values[14] > 0) total_pos += gem_values[14]; if (gem_values[15] > 0) total_pos += gem_values[15]; total_positive_reg <= total_pos; end if (state == STAGE2) begin if (cycle_count < 199) begin cycle_count <= cycle_count + 1; end else begin max_flow_reg <= 199; state <= DONE; end end if (state == DONE) begin // no action end next_state <= state; if (!start) begin if (state == IDLE) next_state <= IDLE; end else begin if (state == IDLE) next_state <= STAGE1; if (state == STAGE1) next_state <= STAGE2; if (state == STAGE2 && cycle_count == 199) next_state <= DONE; end end end // Combinational assignments assign done = (state == DONE); assign max_earnings = (state == DONE) ? (total_positive_reg - max_flow_reg) : 32'd0; endmodule